import{c as r,Q as a,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Prompt Compression for Large Language Models: A Survey","description":"","frontmatter":{"url":"https://arxiv.org/abs/2410.12388","title":"Prompt Compression for Large Language Models: A Survey","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2410.12388,"authors":["Zongqian Li","Yinhong Liu","Yixuan Su","Nigel Collier"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2410.12388v1","pdf_path":"pdfs/2410.12388.pdf","published_date":"2024-10-16T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2024-10-16-prompt-compression-survey-2410-12388.md","filePath":"research/papers/2024-10-16-prompt-compression-survey-2410-12388.md","lastUpdated":1785909234000}'),s={name:"research/papers/2024-10-16-prompt-compression-survey-2410-12388.md"};function i(n,e,l,p,d,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="prompt-compression-for-large-language-models-a-survey" tabindex="-1">Prompt Compression for Large Language Models: A Survey <a class="header-anchor" href="#prompt-compression-for-large-language-models-a-survey" aria-label="Permalink to &quot;Prompt Compression for Large Language Models: A Survey&quot;">​</a></h1><p><strong>Authors</strong>: Zongqian Li, Yinhong Liu, Yixuan Su, Nigel Collier <strong>Published</strong>: October 16, 2024 <strong>Source</strong>: <a href="https://arxiv.org/abs/2410.12388" target="_blank" rel="noreferrer">https://arxiv.org/abs/2410.12388</a> · <a href="https://arxiv.org/html/2410.12388v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2410.12388 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2410.12388" target="_blank" rel="noreferrer">research/papers/pdfs/2410.12388.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Leveraging large language models (LLMs) for complex natural language tasks typically requires long-form prompts to convey detailed requirements and information, which results in increased memory usage and inference costs. To mitigate these challenges, multiple efficient methods have been proposed, with prompt compression gaining significant research interest. This survey provides an overview of prompt compression techniques, categorized into hard prompt methods and soft prompt methods. First, the technical approaches of these methods are compared, followed by an exploration of various ways to understand their mechanisms, including the perspectives of attention optimization, Parameter-Efficient Fine-Tuning (PEFT), modality integration, and new synthetic language. We also examine the downstream adaptations of various prompt compression techniques. Finally, the limitations of current prompt compression methods are analyzed, and several future directions are outlined, such as optimizing the compression encoder, combining hard and soft prompts methods, and leveraging insights from multimodality.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>Prompt compression 領域綜述：以 hard prompt（自然語言層刪減）vs soft prompt（連續向量）二分法系統化整理</li><li>從 attention optimization、PEFT、modality integration、synthetic language 四視角解釋壓縮機制</li><li>整理 downstream 適配與現有方法限制、未來方向（壓縮 encoder 優化、hard+soft 混合、多模態借鑑）</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>綜述性論文，無單一實驗數字；價值在分類法與機制視角</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>2024-10 成稿，未涵蓋其後的 decision-fidelity / scaling paradox 研究線</li><li>soft prompt 方法多需白盒模型訓練，API-only 場景適用性弱</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>作為 <code>.claude/skills/output-compress</code> 相關論文群的領域地圖：workspace 可落地的僅 hard prompt 路線（自然語言層分級刪減），本綜述可用於定位 output-compress 在方法譜系中的座標與盲區。</li><li>「combining hard and soft prompts」等未來方向對 workspace 暫無行動意義，僅供背景。</li></ul>',16)])])}const u=r(s,[["render",i]]);export{c as __pageData,u as default};
